scwin.gridView2_rowOpen = {};
scwin.gridView2_ontoggleclick = function(isCollapsed, rowIndex) {
    var arr = gridView2.getChildrenRowIndexArray(rowIndex);
    var rowSpan = arr.length + 1;
    if (isCollapsed || scwin.gridView2_rowOpen[rowIndex] === true) {
        return;
    }
    gridView2.mergeCell({
        "rowIndex": rowIndex,
        "colIndex": 0,
        "colSpan": 1,
        "rowSpan": rowSpan
    });
    gridView2.mergeCell({
        "rowIndex": rowIndex,
        "colIndex": 1,
        "colSpan": 1,
        "rowSpan": rowSpan
    });
    gridView2.mergeCell({
        "rowIndex": rowIndex,
        "colIndex": 2,
        "colSpan": 1,
        "rowSpan": rowSpan
    });
    gridView2.mergeCell({
        "rowIndex": rowIndex,
        "colIndex": 3,
        "colSpan": 1,
        "rowSpan": rowSpan
    });
    scwin.gridView2_rowOpen[rowIndex] = true;
};

	scwin.checkVal = function() {
		return (document.getElementById('gridView2_cell_8_3') || document.getElementById('mf_gridView2_cell_8_3')).innerText == '여섯번째 제목입니다.';
	}
